                    except ValueError:
                        # If conversion fails, treat as string
                        obj = text[h_val:i]
                elif t_val == 'STRING':
                    obj = text[h_val:i]
                else:
                    obj = text[h_val:i]
                res[key] = obj
        return res

    elif t1 == 'ARRAY':
        res = []
