                    while i < j1 - 1 and text[i:i+1] not in b'\r\n':
                        i += 1
                    while i < j1 - 1 and text[i:i+1] in b'\r\n':
                        i += 1
                    continue

                break

            if i >= j1 - 1:
                break

            h, i, ttt = next_token(text, i)
            if ttt:
                if ttt == 'DICT':
                    obj = parse_obj(text[h:i])
                elif ttt == 'ARRAY':
                    obj = parse_obj(text[h:i])
                elif ttt == 'TRUE':
                    obj = True
                elif ttt == 'FALSE':
                    obj = False
                elif ttt == 'NAME':
                    obj = text[h:i].decode('ascii')
                elif ttt == 'INTEGER' or ttt == 'REAL':
                    try:
                        obj = float(text[h:i]) if b'.' in text[h:i] or b'e' in text[h:i].lower() else int(text[h:i])
