def beginning_next_non_empty_line(bdata, i):
    """ doc
    """
    EOL = b'\r\n'
    while i < len(bdata) and bdata[i:i+1] not in EOL:
        i += 1
    while i < len(bdata) and bdata[i:i+1] in EOL:
